```java
package com.myproj.config;

import org.springframework.boot.context.properties.ConfigurationProperties;
import org.springframework.cloud.openfeign.support.ReadWriteConnectivityStrategy;
import org.springframework.cloud.openfeign.support.HttpConnectTimeoutStrategy;
import org.springframework.cloud.openfeign.support.HttpReadTimeoutStrategy;
import org.springframework.stereotype.Component;

@Component
@ConfigurationProperties(prefix = "app.feign.timeout")
public class FeignTimeoutConfig implements ReadWriteConnectivityStrategy<String> {

    private Integer connectTimeoutMs = 5000;
    private Integer readTimeoutMs = 10000;

    public Integer getConnectTimeoutMs() { return connectTimeoutMs; }
    public void setConnectTimeoutMs(Integer connectTimeoutMs) { this.connectTimeoutMs = connectTimeoutMs; }
    public Integer getReadTimeoutMs() { return readTimeoutMs; }
    public void setReadTimeoutMs(Integer readTimeoutMs) { this.readTimeoutMs = readTimeoutMs; }

    @Override
    public HttpConnectTimeoutStrategy getConnectTimeout() {
        return new HttpConnectTimeoutStrategy(getConnectTimeoutMs());
    }

    @Override
    public HttpReadTimeoutStrategy getReadTimeout() {
        return new HttpReadTimeoutStrategy(getReadTimeoutMs());
    }
}
```

