package com.myproj.client;

import org.apache.http.client.HttpClient;
import org.apache.http.client.methods.AbstractHttpClient;
import org.apache.http.impl.conn.PoolingHttpClientConnectionManager;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import java.time.Duration;

/**
 * HttpClient com pool de conexões configurado para o Feign.
 */
@Configuration
public class FeignHttpClientConfig {

    @Bean
    public HttpClient pooledHttpClient() {
        HttpClient base = HttpClient.newBuilder()
                .connectTimeout(Duration.ofSeconds(5))        // tempo de conexão
                .idleTimeout(Duration.ofSeconds(30))         // tempo ocioso
                .followRedirects(FollowRedirects.NONE)       // sem follow padrão
                .build();

        PoolingHttpClientConnectionManager connectionManager =
                new PoolingHttpClientConnectionManager(base);

        connectionManager.setMaxConnections(10);             // máximo de conexões simultâneas
        connectionManager.setMaxIdleness(Duration.ofMillis(30_000)); // tempo antes de remover da fila
        connectionManager.setMaxRouteConcurrency(5);          // concorrência por rota
        connectionManager.setValidatedConnectionsDuration(Duration.ofMinutes(1));

        // Delegador simples: Apache HttpClient retorna HttpResponse; 
        // Feign pode precisar de HttpRequestWrapper em versões mais antigas? 
        // Em Feign recente, HttpClient.execute() retorna HttpResponse direto.
        // Para compatibilidade, retornamos HttpResponse embutido na estrutura esperada.
        return new AbstractHttpClient() {
            @Override
            public HttpResponse execute(TimeUnit unit, String targetUri, HttpRequest request) 
                    throws IOException {
                return connectionManager.execute(unit, targetUri, request);
            }

            @Override
            public <V> ExecuteRequestAsync<V> executeAsync(TimeUnit unit, String targetUri, HttpRequest request) {
                // adaptável conforme necessidade
                throw new UnsupportedOperationException("use execute");
            }

            @Override
            public <V> CompletableFuture<HttpResponse> executeUnsafeAsync(TimeUnit unit, String targetUri, HttpRequest request) {
                throw new UnsupportedOperationException("use execute");
            }

            @Override
            public CompletableFuture<HttpResponse> executeAsResponseAsync(TimeUnit unit, String targetUri, HttpRequest request, ResponseHandler<HttpResponse> handler) {
                throw new UnsupportedOperationException("use execute");
            }
        };
    }
}
```

