import org.springframework.cloud.openfeign.support.HttpConnectTimeoutStrategy;
import org.springframework.cloud.openfeign.support.HttpReadTimeoutStrategy;
import org.springframework.stereotype.Component;

/**
 * Configuração personalizada de timeout para um cliente Feign específico.
 */
@Component
@ConfigurationProperties(prefix = "app.feign.timeout")
public class PagamentosFeignConfig implements ReadWriteConnectivityStrategy<String> {

    @ConfigurationProperties(key = "connectTimeoutMs")
    private Long connectTimeoutMs = 5000L;

    @ConfigurationProperties(key = "readTimeoutMs")
    private Long readTimeoutMs = 10000L;

    public Long getConnectTimeoutMs() { return connectTimeoutMs; }
    public void setConnectTimeoutMs(Long v) { this.connectTimeoutMs = v; }

    public Long getReadTimeoutMs() { return readTimeoutMs; }
    public void setReadTimeoutMs(Long v) { this.readTimeoutMs = v; }

    @Override
    public HttpConnectTimeoutStrategy getConnectTimeout() {
        return new HttpConnectTimeoutStrategy(Math.toIntExact(connectTimeoutMs));
    }

    @Override
    public HttpReadTimeoutStrategy getReadTimeout() {
        return new HttpReadTimeoutStrategy(Math.toIntExact(readTimeoutMs));
    }
}
```

Note: `HttpConnectTimeoutStrategy` and `HttpReadTimeoutStrategy` constructors take `int`. Values > Integer.MAX_VALUE impossible practically; intCast fine. Better keep int fields.

