        cm.setMaxRouteConcurrency(5);              // ≤5 requisições concorrentes por rota
        cm.setValidatedConnectionsDuration(Duration.ofMinutes(1));

        return new AbstractHttpClient() {
            @Override
            public HttpResponse execute(TimeUnit unit, String targetUri, HttpRequest request)
                    throws Exception {
                return cm.execute(unit, targetUri, request);
            }

            @Override
            public <V> CompletableFuture<HttpResponse> executeAsync(TimeUnit unit, String targetUri, HttpRequest request) {
                // Se precisar assíncrono: delegue a cm.executeAsync(...)
                throw new UnsupportedOperationException("Utilize o método síncrono execute");
            }

            @Override
            public <V> CompletableFuture<HttpResponse> executeUnsafeAsync(TimeUnit unit, String targetUri, HttpRequest request) {
                throw new UnsupportedOperationException("Utilize o método síncrono execute");
            }

            @Override
            public <R extends HttpResponse> HttpResponse executeAsResponse(TimeUnit unit,
                    String targetUri, HttpRequest request,
                    org.apache.http.client.ResponseHandler<R> responseHandler) throws Exception {
                // Não é necessário para casos típicos de Feign; implemente se usar ResponseHandler customizada.
                return cm.executeAsResponse(unit, targetUri, request, responseHandler);
            }

            @Override
            public <V> CompletableFuture<R> executeAsResponseAsync(TimeUnit unit, String targetUri,
                    HttpRequest request, org.apache.http.client.ResponseHandler<V> handler) {
                throw new UnsupportedOperationException("Utilize o método síncrono execute");
            }
        };
    }
}
