package com.exemplo.client;

import com.zaxxer.springcloud.apache.httpclient.ApacheHttpClient;
import org.apache.http.impl.conn.PoolingHttpClientConnectionManager;
import org.apache.http.client.ConnectionManager;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

import java.time.Duration;
import java.util.concurrent.TimeUnit;

@Configuration
public class FeignHttpClientConfig {

    /**
     * HttpClient com pool de conexões dimensionado para os serviços externos.
     * Singleton compartilhado entre todos os @FeignClient da aplicação.
     */
    @Bean(name = "pooled-payments-client")
    public ApacheHttpClient paymentsHttpClient() {

