            pool.setMaxRouteConcurrency(5);               // até 5 req. concorrentes por rota
            pool.setValidatedConnectionsDuration(Duration.ofMinutes(1)); // valida conexões válidas a cada 1 min
        }

        return client;
    }
}
```

